def compute(vars):
    current_2018 = vars["v2"]
    current_2017 = vars["v1"]
    change = current_2018 - current_2017

    return {
        "value": change,
        "trace": {
            "current_2018": current_2018,
            "current_2017": current_2017,
            "change": change,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
